// The skeleton: choose -> recurse -> un-choose.
vector<vector<int>> result;
vector<int> path;

void backtrack(int start) {
    result.push_back(path);              // a COPY (push_back copies)
    for (int i = start; i < nums.size(); i++) {
        path.push_back(nums[i]);         // choose
        backtrack(i + 1);                // recurse
        path.pop_back();                 // un-choose
    }
}

// --- the three variants ---

// COMBINATIONS / SUBSETS: start means "only look forward".
for (int i = start; i < n; i++) { /* ... */ backtrack(i + 1); }

// REUSE ALLOWED: pass i, not i+1.
for (int i = start; i < n; i++) { /* ... */ backtrack(i); }

// PERMUTATIONS: no start; any unused element.
for (int i = 0; i < n; i++) {
    if (used[i]) continue;
    used[i] = true;  path.push_back(nums[i]);
    backtrack();
    path.pop_back(); used[i] = false;
}

// DUPLICATE INPUT: sort, then skip equal siblings.
sort(nums.begin(), nums.end());
for (int i = start; i < n; i++) {
    if (i > start && nums[i] == nums[i - 1]) continue;
    /* ... */
}

